function calcIRR(inv, annual, terminal, yrs) {
  if (annual<=0||inv<=0) return 0;
  let r=0.08;
  for (let i=0;i<300;i++) {
    let npv=-inv,dn=0;
    for (let t=1;t<=yrs;t++) {
      const d=Math.pow(1+r,t);
      npv+=annual/d; dn-=(t*annual)/Math.pow(1+r,t+1);
    }
    npv+=terminal/Math.pow(1+r,yrs);
    dn-=(yrs*terminal)/Math.pow(1+r,yrs+1);
    if (Math.abs(dn)<1e-6) break;
    const nr=r-npv/dn;
    if (Math.abs(nr-r)<1e-5) break;
    r=nr;
  }
  return Math.max(r*100,0);
}

function calcPricing(nights, base, cleaningCostPerNight=0, commPct=0, minNights=2) {
  // cleaningCostPerNight = costo interno tuyo, NO se cobra al huésped
  let rate=base, label="Estándar", available=true, warningMsg="";

  if (nights < minNights) {
    available = true;  // no bloquear, solo advertir
    warningMsg = `Por debajo del mínimo recomendado (${minNights} noches)`;
    rate = base * 1.5;
    label = `+50% (bajo mín. recomendado)`;
  } else if (nights === 1) {
    rate = base * 1.5;
    label = "+50% tarifa 1 noche";
  } else if (nights === 2) {
    rate = base * 1.2;
    label = "+20% tarifa 2 noches";
  } else if (nights >= 30) {
    rate = base * 0.75;
    label = "−25% estadía mensual";
  } else if (nights === 21) {
    rate = base * 0.8;
    label = "−20% 3 semanas";
  } else if (nights === 14) {
    rate = base * 0.85;
    label = "−15% 2 semanas";
  } else if (nights === 7) {
    rate = base * 0.9;
    label = "−10% semanal";
  } else {
    label = "Precio estándar";
  }

  const perNight    = Math.round(rate);
  const bruto       = perNight * nights;           // lo que paga el huésped
  const costoLimpieza = cleaningCostPerNight * nights; // costo tuyo interno
  const comision    = Math.round(bruto * commPct / 100);
  const netoHuesped = bruto - comision;            // lo que recibís vos
  const netoReal    = netoHuesped - costoLimpieza; // ganancia real descontando limpieza

  return {
    total: bruto,           // precio bruto al huésped (sin limpieza)
    neto: netoHuesped,      // lo que recibís después de comisión
    netoReal,               // ganancia real (descontando limpieza interna)
    comision,
    costoLimpieza,
    perNight,
    label, available, warningMsg,
  };
}

